import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Tiled kernel: CTA-level spatial tiling with shared-memory staging of the
// reusable input patch (halo included). Each block computes an
// OH_TILE x OW_TILE output tile for CcPerBlock channels; the corresponding
// input patch is loaded once into shared memory and reused by every tap and
// every output row of the tile instead of being re-read from global memory.
template <typename T>
__global__ void dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout, int num_w_tiles)
{
  constexpr int Threads     = 128;
  constexpr int OH_TILE     = 16;
  constexpr int OW_TILE     = 32;
  constexpr int PVec        = (OH_TILE * OW_TILE) / Threads;
  constexpr int CcPerBlock  = 4;
  constexpr int KChunk      = 8;
  const int tid = threadIdx.x;
  const int n      = blockIdx.z;
  const int c_base = blockIdx.y * CcPerBlock;
  const int wt  = blockIdx.x % num_w_tiles;
  const int ht  = blockIdx.x / num_w_tiles;
  const int oh0 = ht * OH_TILE;
  const int ow0 = wt * OW_TILE;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(C, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride((int64_t)K, Int<1>{})
  );
  // Shared-memory tile geometry (depends on runtime stride/dilation).
  const int cols_tile    = (OW_TILE - 1) * stride + 1;
  const int rows_tile_mx = (OH_TILE - 1) * stride + (KChunk - 1) * dilation + 1;
  extern __shared__ char smem_raw[];
  T* sX_raw = reinterpret_cast<T*>(smem_raw);
  T* sW_raw = sX_raw + (size_t)CcPerBlock * rows_tile_mx * cols_tile;
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CcPerBlock>{}, rows_tile_mx, cols_tile),
      make_stride((int64_t)rows_tile_mx * cols_tile, (int64_t)cols_tile, Int<1>{})
  );
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{})
  );
  // Thread -> output mapping inside the tile (PVec outputs per thread).
  int  orow[PVec];
  int  ocol[PVec];
  bool valid[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int o  = tid + i * Threads;
    int r  = o / OW_TILE;
    int cl = o - r * OW_TILE;
    orow[i]  = r;
    ocol[i]  = cl;
    valid[i] = (oh0 + r < Hout) && (ow0 + cl < Wout);
  }
  // Accumulators initialized with bias if present.
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < C) {
      bval = (float)B[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }
  const int base_ih0 = oh0 * stride - padding;
  const int base_iw  = ow0 * stride - padding;
  for (int k0 = 0; k0 < K; k0 += KChunk) {
    const int kc        = min(KChunk, K - k0);
    const int rows_tile = (OH_TILE - 1) * stride + (kc - 1) * dilation + 1;
    const int base_ih   = base_ih0 + k0 * dilation;
    // Cooperatively stage this chunk of depthwise weights.
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int kg = k0 + kk;
      #pragma unroll
      for (int cc = 0; cc < CcPerBlock; ++cc) {
        int c = c_base + cc;
        T wv = T(0);
        if (c < C && kg < K) {
          wv = mW(c, kg);
        }
        sW(cc, kk) = wv;
      }
    }
    // Cooperatively stage the input patch (zero padded outside the image).
    const int total = CcPerBlock * rows_tile * cols_tile;
    for (int idx = tid; idx < total; idx += Threads) {
      int col = idx % cols_tile;
      int t2  = idx / cols_tile;
      int row = t2 % rows_tile;
      int cc  = t2 / rows_tile;
      int c   = c_base + cc;
      int ih  = base_ih + row;
      int iw  = base_iw + col;
      T xv = T(0);
      if (c < C && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        xv = mX(c, ih, iw);
      }
      sX(cc, row, col) = xv;
    }
    __syncthreads();
    // Consume the staged tile: every tap reads shared memory only.
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      const int rbase = orow[i] * stride;
      const int cbase = ocol[i] * stride;
      #pragma unroll
      for (int kk = 0; kk < KChunk; ++kk) {
        if (kk >= kc) break;
        const int row = rbase + kk * dilation;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          acc[cc][i] += (float)sX(cc, row, cbase) * (float)sW(cc, kk);
        }
      }
    }
    __syncthreads();
  }
  // Store results.
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= C) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      mY(c, oh0 + orow[i], ow0 + ocol[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}
// Fallback: original direct kernel, used only when the staged tile would
// not fit into shared memory (e.g. very large stride or dilation).
template <typename T>
__global__ void dwconv2d_k1_direct_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout)
{
  constexpr int Threads     = 128;
  constexpr int PVec        = 2;
  constexpr int CcPerBlock  = 4;
  constexpr int KChunk      = 64;
  const int tid = threadIdx.x;
  const int n         = blockIdx.z;
  const int c_tile    = blockIdx.y;
  const int c_base    = c_tile * CcPerBlock;
  const int P_total   = Hout * Wout;
  const int PTile     = Threads * PVec;
  const int p_block   = blockIdx.x * PTile;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(C, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride((int64_t)K, Int<1>{})
  );
  __shared__ T sW_raw[CcPerBlock * KChunk];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{})
  );
  int   p_idx[PVec];
  int   oh_arr[PVec];
  int   ow_arr[PVec];
  int   base_ih0[PVec];
  int   iw_arr[PVec];
  bool  wv_arr[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      int iw = ow * stride - padding;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
      iw_arr[i] = iw;
      base_ih0[i] = oh * stride - padding;
      wv_arr[i] = (iw >= 0 && iw < Win);
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      iw_arr[i] = -1;
      base_ih0[i] = 0;
      wv_arr[i] = false;
    }
  }
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < C) {
      bval = (float)B[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }
  for (int k0 = 0; k0 < K; k0 += KChunk) {
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int k_global = k0 + kk;
      #pragma unroll
      for (int cc = 0; cc < CcPerBlock; ++cc) {
        int c = c_base + cc;
        T wval = T(0);
        if (c < C && k_global < K) {
          wval = mW(c, k_global);
        }
        sW(cc, kk) = wval;
      }
    }
    __syncthreads();
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      if (!wv_arr[i]) continue;
      int iw = iw_arr[i];
      int ih0 = base_ih0[i];
      #pragma unroll
      for (int kk = 0; kk < KChunk; ++kk) {
        int k_global = k0 + kk;
        if (k_global >= K) break;
        int ih = ih0 + k_global * dilation;
        if ((unsigned)ih >= (unsigned)H) continue;
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int c = c_base + cc;
          if (c >= C) continue;
          float xval = (float)mX(c, ih, iw);
          float wval = (float)sW(cc, kk);
          acc[cc][i] += xval * wval;
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= C) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for kernel width = 1");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * (int64_t)padding - (int64_t)dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * (int64_t)padding - (int64_t)dilation * (1 - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C, Hout, Wout}, x.options());
  constexpr int Threads     = 128;
  constexpr int OH_TILE     = 16;
  constexpr int OW_TILE     = 32;
  constexpr int CcPerBlock  = 4;
  constexpr int KChunk      = 8;
  constexpr int PVecDirect  = 2;
  const int64_t cols_tile    = (int64_t)(OW_TILE - 1) * stride + 1;
  const int64_t rows_tile_mx = (int64_t)(OH_TILE - 1) * stride + (int64_t)(KChunk - 1) * dilation + 1;
  const size_t smem_bytes = sizeof(float) *
      ((size_t)CcPerBlock * (size_t)rows_tile_mx * (size_t)cols_tile + (size_t)CcPerBlock * KChunk);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes <= (size_t)46 * 1024) {
    const int64_t num_w_tiles = (Wout + OW_TILE - 1) / OW_TILE;
    const int64_t num_h_tiles = (Hout + OH_TILE - 1) / OH_TILE;
    dim3 block(Threads);
    dim3 grid(
        (unsigned)(num_w_tiles * num_h_tiles),
        (unsigned)((C + CcPerBlock - 1) / CcPerBlock),
        (unsigned)N
    );
    dwconv2d_k1_kernel<float><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)Win,
        (int)K, (int)stride, (int)padding, (int)dilation,
        (int)Hout, (int)Wout, (int)num_w_tiles
    );
  } else {
    const int64_t P_total = Hout * Wout;
    const int64_t PTile = Threads * PVecDirect;
    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + PTile - 1) / PTile),
        (unsigned)((C + CcPerBlock - 1) / CcPerBlock),
        (unsigned)N
    );
    dwconv2d_k1_direct_kernel<float><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)Win,
        (int)K, (int)stride, (int)padding, (int)dilation,
        (int)Hout, (int)Wout
    );
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1 kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

dwconv2d_ext = load_inline(
    name="cute_dwconv2d_asym_k1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with asymmetric kernel (kernel_size x 1),
    implemented with one custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        # Parameter holder matches nn.Conv2d depthwise layout and state_dict naming.
        self.conv2d = nn.Conv2d(
            self.in_channels,
            self.in_channels,
            kernel_size=(self.kernel_size, 1),
            stride=self.stride,
            padding=self.padding,
            dilation=self.dilation,
            groups=self.in_channels,
            bias=bias,
        )
        self._ext = dwconv2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.conv2d.weight.contiguous(),
            self.conv2d.bias if self.conv2d.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

